#include <iostream>
#include <vector>
using namespace std;
int main() {
    int r, c, s, min;
    // 输入调研区域的长、宽，正方形电站的边长，以及最低发电量
    cin >> r >> c >> s >> min;

    // 创建一个二维矩阵存储每个区域的发电量
    vector<vector<int>> matrix(r, vector<int>(c));
    // 输入矩阵的每个元素，即每个区域的发电量
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            cin >> matrix[i][j];
        }
    }

    int ans = 0;  // 记录满足条件的正方形区域个数
    // 遍历所有可能的正方形区域
    for (int i = s; i <= r; i++) {
        for (int j = s; j <= c; j++) {
            int square = 0;  // 记录当前正方形区域的总发电量
            // 计算以(i, j)为右下角的正方形的总发电量
            for (int x = i - s; x < i; x++) {
                for (int y = j - s; y < j; y++) {
                    square += matrix[x][y];
                }
            }
            // 如果当前正方形区域的总发电量满足最低要求，则计数+1
            if (square >= min) ans++;
        }
    }

    // 输出满足条件的正方形区域个数
    cout << ans << endl;
    return 0;
}
